        Map<String, Long> cache = new HashMap<>();
        Set<String> cachedQueries = new HashSet<>();

        // Calculate hit rate
        JavaRDD<String> hitRateData = onsiteAttributedData.mapPartitions(partition -> {
            long cacheHits = 0;
            long cacheMisses = 0;
            Map<String, Long> partitionCache = new HashMap<>();
            Set<String> partitionCachedQueries = new HashSet<>();

            for (String query : partition) {
                if (topFrequentQueries.contains(query)) {
                    if (cachedQueries.contains(query)) {
                        cacheHits++;
                        if (partitionCache.containsKey(query)) {
                            partitionCache.put(query, partitionCache.get(query) + 1);
                        } else {
                            partitionCache.put(query, 1);
                        }
                    } else {
                        cacheMisses++;
                        // Simulate cache retrieval and caching
                        System.out.println("Cache miss for query: " + query);
                        cache.put(query, System.currentTimeMillis());
                        cachedQueries.add(query);
                        partitionCache.put(query, 1);
                        partitionCachedQueries.add(query);
                    }
                }
            }
            return List.of(String.format("Cache Hits: %d, Cache Misses: %d", cacheHits, cacheMisses)).iterator();
        });

        // Print hit rate
        hitRateData.foreach(System.out::println);

        spark.stop();
    }
}
