    }

    for (let i = 0; i < data1.length; i++) {
      const row1 = data1[i];
      const row2 = data2[i];

      for (const columnKey in row1) {
        if (row1.hasOwnProperty(columnKey)) {
          const value1 = row1[columnKey];
          const value2 = row2[columnKey];

          if (value1 !== value2) {
            discrepancies.push({
              row: i + 1,
              column: columnKey,
              file1Value: value1,
              file2Value: value2,
            });
          }
        }
      }
    }

    return discrepancies;
  } catch (error) {
    console.error("Error comparing Excel files:", error);
    return [];
  }
}

