import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.stereotype.Service;

import java.io.BufferedReader;
import java.io.FileReader;
import java.io.FileWriter;
import java.io.IOException;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.util.List;

@Service
public class QueryScheduler {

    private final JdbcTemplate jdbcTemplate;

    private static final String SQL_QUERY_FILE = "query.sql";
    private static final String RESULT_FILE = "result.txt";

    @Autowired
    public QueryScheduler(JdbcTemplate jdbcTemplate) {
        this.jdbcTemplate = jdbcTemplate;
    }

    @Scheduled(cron = "0 0 * * * *") // Runs every hour
    public void executeQueryAndStoreResult() {
        try {
            String sqlQuery = readSqlQueryFromFile(SQL_QUERY_FILE);
            List<String> results = executeSqlQuery(sqlQuery);
            storeResultsToFile(results, RESULT_FILE);
        } catch (IOException | SQLException e) {
            System.err.println("Error executing query and storing result: " + e.getMessage());
            e.printStackTrace();
        }
    }

    private String readSqlQueryFromFile(String filePath) throws IOException {
        try (BufferedReader reader = new BufferedReader(new FileReader(filePath))) {
            return reader.readLine(); // Assuming the query is on a single line
        }
    }

    private List<String> executeSqlQuery(String sqlQuery) throws SQLException {
        return jdbcTemplate.queryForList(sqlQuery, String.class);
    }

    private void storeResultsToFile(List<String> results, String filePath) throws IOException {
        try (FileWriter writer = new FileWriter(filePath, true)) { // Append to file
            for (String result : results) {
                writer.write(result + "\n");
            }
        }
    }
}
